/* Evolvlings: path conversations of era 8, La Vigilia (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 8:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   Another generation has passed since Los Vientos Vendidos. How era 7 ended (m7_unico / m7_libre / m7_manos)
   is still in the flags and changes a few lines and options.
   Those Who Hear, the dreamers' cult born in era 2, woke the Root on purpose, and the Root speaks through the
   dreamers' mouths. It is thirsty, afraid and it remembers: it wants back Hollín, the Star moth who drank first.
   The House of the Mushroom prospers, because its mushrooms only grow on black sap.
   The nine peoples you bring together set the u8_* flags; with all nine, the final dilemma offers The Root with a Vote
   (rpg/data-eras.js derives e8_nueve). The m8_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era8.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: la Raíz que habla, Hollín, Los Que Oyen, la Seta, los robles y el final ==================== */

  /* ---------- Prado Aurora: las raíces de la plaza, los faroles y el Vado ---------- */
  add("aurora", {
    "e8-raices": { kind: "encuentro", need: { era: 8, layer: 1 }, first: true, who: {}, start: "a", nodes: {
      a: { say: [[null, "Entre las piedras de la plaza del Prado asoman raíces negras, gruesas como brazos. Levantan las baldosas. Los vecinos caminan por los bordes, sin pisarlas."],
                 [null, "En medio de la plaza, un niño del Barrio se quedó dormido sentado en una raíz. Tiene los ojos abiertos. Habla con una voz que no es de niño: lenta, grave, con olor a tierra mojada."],
                 [null, "«Tengo sed. Tengo miedo. Me acuerdo de todo. Me acuerdo de la primera boca que bebió de mí. Díganle que vuelva»."],
                 [null, "La madre lo despierta sacudiéndolo. El niño llora y no se acuerda de nada. Alrededor, la gente se mira. Hace siglos que la Raíz duerme. Ahora habla."]],
           opts: [{ t: "«¿Desde cuándo habla así?»", go: "cuando", once: true },
                  { t: "«¿Esto pasa todas las noches desde el Canto Único?»", go: "unico", cNeed: "m7_unico", once: true },
                  { t: "«¿Por qué nadie les creyó a los soñadores?»", go: "libre", cNeed: "m7_libre", once: true },
                  { t: "Cortar las raíces de la plaza", go: "cortar" },
                  { t: "Dejarles un balde de agua", go: "agua" },
                  { t: "Proponer que el Barrio haga una ronda de noche, para cuidar a los que duermen", go: "ronda" }] },
      cuando: { say: [[null, "Una vendedora de fruta te contesta sin dejar de mirar al niño."],
                      [null, "«Desde que Los Que Oyen bajaron a la Tumba y la despertaron. Dicen que lo hicieron a propósito. Que la Raíz tenía derecho a hablar. Ahora habla por los chicos que se duermen en la plaza»."]], back: "a" },
      unico: { say: [[null, "Un viejo señala la fuente. Sobre el agua flota una estrella opaca, chica, que no brilla. Una Estrella Muda, de las que nacieron con el Canto Único."],
                     [null, "«Todas las noches le cantamos lo mismo, y todas las noches está más harta. Mire la estrella: antes estaba quieta. Ahora tiembla cuando el niño habla»."]], back: "a" },
      libre: { say: [[null, "La vendedora se encoge de hombros."],
                     [null, "«Porque desde que se rompieron los molinos, todo lo que se dice corre un día y se olvida. Los del Fondo dijeron que la Raíz hablaba. Pensamos que era otro rumor. Hasta que habló aquí, en la plaza, con la boca de un niño»."]], back: "a" },
      cortar: { say: [[null, "Pides un hacha prestada. Cortas la raíz más gruesa, la que levanta la fuente. Sale una savia negra y tibia que huele a sótano."],
                      [null, "Esa noche, en todas las casas del Prado, los que duermen gritan a la vez. Al día siguiente, la raíz volvió a salir, más gruesa, un poco más allá."]], end: { xp: 10, flag: "e8_raicesCortadas" } },
      agua: { say: [[null, "Llenas un balde en la fuente y lo dejas al lado de la raíz. Nadie te mira bien. Alguien murmura que así se alimenta a un perro que muerde."],
                    [null, "En la mañana el balde está vacío y seco, como si nunca hubiera tenido agua. La raíz no creció. Tampoco se fue. El niño del Barrio durmió sin hablar."]], end: { xp: 14, flag: "e8_raicesAgua" } },
      ronda: { say: [[null, "Hablas con los vecinos del Barrio. Esa noche arman turnos: dos despiertos por cuadra, con faroles, que despiertan con cuidado a cualquiera que hable dormido."],
                     [null, "Nadie corta raíces. Nadie las riega. Solo se cuidan. Al tercer día, la madre del niño se suma a la ronda con su propio farol."],
                     [null, "«Si la Raíz quiere hablar, que hable. Pero no por la boca de nuestros chicos mientras nadie mira»."]], end: { xp: 20, flag: ["e8_rondaBarrio", "u8_barrio"] } },
    } },

    "e8-fanal": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { fanal: "Fanal, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la calle de las Casas del Farol, un hombre de unos cincuenta años sube faroles nuevos a los postes, uno detrás de otro. Son más grandes que los de siempre. Arden con un aceite que no se apaga."],
                 ["fanal", "Fanal, de las Casas. Las raíces no salen donde hay luz. Ya lo probamos: en nuestra calle no asoma ninguna. Entonces, más luz. Toda la noche, todas las noches."],
                 ["fanal", "El Barrio dice que no le alcanza para faroles. Que se compren. Nosotros ya pagamos los nuestros."]],
           opts: [{ t: "«¿De dónde sale ese aceite que no se apaga?»", go: "aceite", once: true },
                  { t: "«¿Usan la Estrella Muda de la fuente como farol?»", go: "estrella", cNeed: "m7_unico", once: true },
                  { t: "Ayudarlo a encender toda la calle", go: "encender" },
                  { t: "«Apaguen todo una noche. Veamos qué hace la Raíz.»", go: "apagar" },
                  { t: "«Que las Casas alumbren también las calles del Barrio.»", go: "barrio" }] },
      aceite: { say: [["fanal", "Del Cráter. El Gremio embotella la savia que hierve en las grietas. Arde para siempre."],
                      ["fanal", "Sí, ya sé. Es savia. Siempre fue savia, si vamos al caso. Mi familia lleva doscientos años encendiendo el Prado con lo que sale del suelo. No me lo diga como si fuera noticia."]], back: "a" },
      estrella: { say: [["fanal", "La intentamos colgar. No da luz. Se queda opaca, flotando, mirando hacia abajo. La devolvimos a la fuente."],
                        ["fanal", "Mi abuela decía que esas estrellas están llenas de promesas que nadie quiso hacer. Que pesan. Yo no le creía. La cargué en brazos. Pesa."]], back: "a" },
      encender: { say: [[null, "Pasas la tarde con él, subiendo faroles. Al anochecer, la calle está blanca de luz. Las raíces del borde se retiran, despacio, hacia el Barrio."],
                        ["fanal", "¿Ve? Funciona."],
                        [null, "Funciona. Al día siguiente hay el doble de raíces en el Barrio, donde no hay faroles."]], end: { xp: 10, flag: "e8_fanalLuz" } },
      apagar: { say: [["fanal", "¿Apagar? ¿Con la Raíz despierta?"],
                      [null, "Le cuesta. Pero esa noche apaga los faroles de su propia casa. Se sientan en el escalón, a oscuras. Desde el suelo sube un ruido suave, como alguien que respira."],
                      ["fanal", "No viene. No crece. Solo respira. Pensé que la luz la espantaba. A lo mejor la luz le duele. A lo mejor la luz le recuerda algo."]], end: { xp: 16, flag: "e8_fanalApaga" } },
      barrio: { say: [["fanal", "¿Alumbrar el Barrio? ¿Con nuestro aceite?"],
                      [null, "Discute contigo un buen rato. Después baja a la plaza y mira las raíces que salen entre las casas del Barrio, donde duermen los chicos que hablan dormidos."],
                      ["fanal", "Está bien. Un farol por cuadra, del lado del Barrio. Lo pago yo. Que nadie diga que las Casas solo alumbran su calle. Aunque es lo que hicimos siempre."]], end: { xp: 20, flag: ["e8_fanalBarrio", "u8_luz"] } },
    } },

    "e8-vado": { kind: "dialogo", need: { era: 8, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "Una mañana, al salir de casa, ves una raíz negra que cruza el Vado de lado a lado, por debajo del agua. Es delgada, como un dedo largo. Toca el río y se queda quieta."],
                 [null, "Tu criatura la mira, desconfiada. Después se acerca y la huele. La raíz no se mueve."],
                 [null, "Esa noche, desde la casa, oyes que algo tararea bajito, en el agua. No es tu criatura."]],
           opts: [{ t: "Escuchar qué tararea", go: "oir", once: true },
                  { t: "Cantarle la canción que le compraste al Coro", go: "comprada", cNeed: "m7_vadoComprada" },
                  { t: "Cantarle la canción que escribiste para el Vado", go: "propia", cNeed: "m7_vadoPropia" },
                  { t: "Cantarle lo primero que se te ocurra, ya que el Vado no tiene canción", go: "sin", cNeed: "m7_vadoSin" },
                  { t: "Cavar una zanja alrededor de la casa", go: "zanja" },
                  { t: "Dejar que beba del río", go: "beber" }] },
      oir: { say: [[null, "Te sientas en la orilla, en la oscuridad. Es una tonada torpe, de tres notas, que se repite. Te suena. Tardas en darte cuenta: es lo que se canta en el Vado. Lo aprendió de oírlo."]], back: "a" },
      comprada: { say: [[null, "Le cantas la canción del Coro, la del lugar donde se cruza el río y la gente se espera. La raíz tiembla en el agua, como si se riera."],
                        [null, "Al día siguiente, la raíz se fue. Pero en todas las casas del Prado la gente amaneció tarareando la canción del Vado. La Raíz la cantó en sueños por todas las bocas. Una canción comprada se pega en todos lados, también ahí abajo."]], end: { xp: 14, flag: "e8_vadoCanta" } },
      propia: { say: [[null, "Le cantas la canción que escribiste aquella tarde, la que suena mal. Tu criatura la canta contigo, peor que nunca."],
                      [null, "La raíz se queda quieta, escuchando. No la repite. No la entiende. Al amanecer, se retira despacio hacia el fondo."],
                      [null, "Una canción que no se pega es una canción que la Raíz no puede llevarse. Te quedas con eso todo el día."]], end: { xp: 18, flag: "e8_vadoCanta" } },
      sin: { say: [[null, "Le cantas lo primero que te sale. Es una tontería sobre tu criatura y un pez. La raíz se enrosca un poco, como un gato."],
                   [null, "Al día siguiente vuelve, y al otro. Parece que le gusta que alguien le cante algo distinto cada noche."]], end: { xp: 14, flag: "e8_vadoCanta" } },
      zanja: { say: [[null, "Pasas el día cavando una zanja alrededor de tu casa y la llenas de piedras. Tu criatura te ayuda a su manera: tira tierra para todos lados."],
                     [null, "La raíz no cruza la zanja. Se queda en el río. Pero esa noche la oyes golpear las piedras, despacio, toda la noche, como quien toca una puerta."]], end: { xp: 10, flag: "e8_vadoZanja" } },
      beber: { say: [[null, "No haces nada. La raíz bebe del Vado toda la noche. En la mañana el río está un poco más bajo, y la raíz un poco más gruesa."],
                     [null, "Tu criatura se sienta al lado, a mirarla. Desde ese día la saluda cada mañana, como a un vecino raro."]], end: { xp: 12, flag: "e8_vadoBebe" } },
    } },
  });

  /* ---------- Cráter Tibio: la savia que hierve ---------- */
  add("crater", {
    "e8-hervor": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { fumarola: "Fumarola, del Gremio de la Brasa" }, start: "a", nodes: {
      a: { say: [[null, "En las grietas del Cráter la savia negra hierve. Burbujea despacio, como sopa espesa. Una mujer con guantes de cuero hasta los codos la junta con un cucharón y la vuelca en frascos."],
                 ["fumarola", "Fumarola, del Gremio. Mírela: arde sola, sin mecha, y no se apaga nunca. Las Casas del Farol nos compran todo lo que sacamos. El Gremio no tuvo un año así en cinco generaciones."],
                 ["fumarola", "Mis aprendices dicen que de noche las grietas hablan. Que piden que no les saquemos más. Yo no oigo nada. Yo tengo cuarenta bocas que alimentar en el taller."]],
           opts: [{ t: "«¿Qué dicen las grietas, exactamente?»", go: "dicen", once: true },
                  { t: "Comprarle un frasco", go: "comprar", fx: { cost: 15 } },
                  { t: "Tapar las grietas con piedra", go: "tapar" },
                  { t: "«Dejen la mitad en las grietas, para que se enfríen solas.»", go: "mitad" }] },
      dicen: { say: [["fumarola", "Que les duele. Que tienen sed. Lo mismo que dicen los chicos del Prado cuando se duermen en la plaza. Lo mismo que dice todo el mundo este año."],
                     ["fumarola", "Si algo te duele y das de beber igual, ¿quién tiene la culpa? Yo digo que la grieta."]], back: "a" },
      comprar: { say: [[null, "Te da un frasco tibio. Adentro, una llama negra se mueve sola, como un pez."],
                       [null, "Esa noche lo dejas en la mesa. La llama se inclina toda la noche hacia el suelo, hacia abajo, hacia el Corazón. Tu criatura no se acerca a la mesa."]], end: { xp: 10, flag: "e8_hervorFrasco" } },
      tapar: { say: [[null, "Cargas piedras toda la tarde y tapas tres grietas grandes. Fumarola te mira con los brazos cruzados."],
                     ["fumarola", "Tres. Hay trescientas. Y mañana mis aprendices van a cavar alrededor de sus piedras. Usted cree que tapó algo. Lo que hizo es darles más trabajo a ellos."]], end: { xp: 12, flag: "e8_hervorTapa" } },
      mitad: { say: [["fumarola", "¿La mitad? ¿Sabe cuánto es la mitad?"],
                     [null, "Lo discute con el taller entero. Los aprendices más jóvenes, los que oyen hablar a las grietas, votan que sí. Los viejos, que no. Fumarola decide."],
                     ["fumarola", "La mitad. Por un año. Si en un año mis cuarenta comen menos, vengo a buscarlo a su casa. Y si las grietas se callan, no le voy a dar las gracias. Le voy a pedir que me explique por qué."]], end: { xp: 20, flag: ["e8_hervorEnfria", "u8_fuego"] } },
    } },
  });

  /* ---------- Bosque Hondo: los robles que se inclinan y la zona que pide la Raíz ---------- */
  add("forest", {
    "e8-robles": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { madreselva: "Madreselva, alcaldesa del Bosque" }, start: "a", nodes: {
      a: { say: [[null, "En el Bosque Hondo, todos los robles se inclinan hacia el mismo lado: hacia el Corazón. Como gente que escucha algo lejos. Algunos ya tocan el suelo con las ramas."],
                 [null, "Una mujer mayor, con el pelo trenzado con enredaderas, dirige a un grupo que ata los troncos con cuerdas gruesas a estacas clavadas en la tierra."],
                 ["madreselva", "Madreselva, alcaldesa del Bosque. Si se caen, se cae el Bosque. Si se cae el Bosque, el Concejo del Musgo no tiene qué gobernar. Así que los atamos. Uno por uno. Llevamos doscientos."]],
           opts: [{ t: "«¿Qué escuchan los robles?»", go: "escuchan", once: true },
                  { t: "Ayudar a atar los robles", go: "atar" },
                  { t: "«Déjelos inclinarse. Son árboles, saben lo que hacen.»", go: "dejar" },
                  { t: "«Antes de atarlos, que el Concejo escuche lo que oyen.»", go: "oir" }] },
      escuchan: { say: [["madreselva", "Lo mismo que todo el mundo: la sed. Los robles tienen las raíces más hondas del Claro. Tocan a la Raíz de verdad. Ellos la oyeron antes que nadie."],
                        ["madreselva", "Mi abuela decía que los robles se inclinan cuando alguien va a morir. Yo digo que se inclinan cuando alguien va a pedir algo. Y que conviene estar parada antes de que pida."]], back: "a" },
      atar: { say: [[null, "Pasas el día con las cuerdas. Al anochecer, quedan cuarenta robles más atados, tensos, con las cuerdas cantando cuando sopla el viento."],
                    ["madreselva", "Gracias. Mañana seguimos."],
                    [null, "Esa noche, una cuerda se corta sola. El roble no se cae. Se inclina un poco más, despacio, como alguien que se suelta de una mano."]], end: { xp: 12, flag: "e8_roblesAtados" } },
      dejar: { say: [["madreselva", "¿Saben lo que hacen? Los árboles no saben nada. Crecen hacia donde hay algo. Eso no es saber."],
                     [null, "Pero manda a su gente a descansar. Esa noche, sin cuerdas, los robles se inclinan un poco más. Al amanecer, un sendero nuevo se abrió entre ellos: todos señalan el mismo camino, hacia el Corazón."]], end: { xp: 14, flag: "e8_roblesLibres" } },
      oir: { say: [["madreselva", "¿Escuchar a los robles? ¿En el Concejo? Van a pensar que me volví loca."],
                   [null, "Igual lo hace. Esa noche, el Concejo del Musgo entero se acuesta en el suelo del Bosque, con la oreja contra la tierra, entre las raíces."],
                   [null, "Al amanecer se levantan callados. Nadie dice lo que oyó. Pero esa mañana, Madreselva manda a desatar diez robles, los más viejos, y los deja inclinarse."],
                   ["madreselva", "No pide. Todavía no. Pero va a pedir algo del Bosque. Lo sé. Y quiero que el Concejo esté de pie cuando lo haga."]], end: { xp: 20, flag: ["e8_roblesOidos", "u8_planta"] } },
    } },

    "e8-zona": { kind: "encuentro", need: { era: 8, layer: 3 }, who: { madreselva: "Madreselva, alcaldesa del Bosque", raiz: "La Raíz, por boca de los soñadores" }, start: "a", nodes: {
      a: { say: [[null, "En el claro más hondo del Bosque, la alcaldesa espera de pie con el Concejo detrás. Frente a ellos, sentada contra un roble inclinado, una soñadora del Fondo duerme con los ojos abiertos."],
                 ["raiz", "Me apretaron. Mil años me apretaron. Arriba de mí construyeron, cavaron, cantaron, prometieron. Quiero un lugar. Uno. Donde nadie pise. Donde pueda beber sin que me saquen."],
                 ["madreselva", "Madreselva, alcaldesa del Bosque. Pide el Bosque. Lo sabía. Pero se lo puede dar otra cosa. La Hondonada, por ejemplo. Allá ya hay savia. Allá viven las sombras. Nadie la quiere."]],
           opts: [{ t: "«¿La Hondonada es suya para darla?»", go: "suya", once: true },
                  { t: "«¿Qué pasa con la zona que le demos?»", go: "pasa", once: true },
                  { t: "Ceder el Bosque Hondo a la Raíz", go: "bosque" },
                  { t: "Ceder la Hondonada, como propone Madreselva", go: "hondonada" },
                  { t: "Negarte: ninguna zona", go: "negar" }] },
      suya: { say: [["madreselva", "No. No es mía. Por eso es fácil darla."],
                    [null, "Lo dice sin bajar la vista. Detrás, alguien del Concejo se mira las manos."],
                    ["madreselva", "Ser alcaldesa es eso: negociar con lo que una tiene, y cuando no alcanza, con lo que tienen los demás. No me lo reproche si no va a ofrecer otra cosa."]], back: "a" },
      pasa: { say: [["raiz", "Me quedo. Para siempre. Nadie entra, nadie sale. Lo que crezca ahí, crece para mí."],
                    ["madreselva", "Una zona cerrada. Para siempre. Por las generaciones que vengan. Y a cambio, deja de pedir en las demás. Eso dice. Eso dijo también la última vez que alguien le prometió algo."]], back: "a" },
      bosque: { say: [[null, "Madreselva se queda quieta mucho rato. Después asiente, una sola vez."],
                      [null, "Esa semana, el Concejo del Musgo sale del Bosque con lo que puede cargar. Los robles se inclinan del todo, hasta tocar el suelo, y la tierra se cierra sobre los senderos."],
                      ["madreselva", "Le di lo único que era mío. Ahora no gobierno nada. Debería sentirme peor. Me siento como quien deja de cargar algo muy pesado."]], end: { xp: 30, flag: ["m8_zonaBosque", "m8_zonaCedida"] } },
      hondonada: { say: [[null, "La soñadora asiente dormida. Esa noche, la savia negra sube en la Hondonada hasta las rodillas. Las sombras que viven ahí salen con lo que pueden cargar, en fila, hacia ningún lado."],
                         ["madreselva", "Ya está. El Bosque queda en pie. El Concejo queda en pie."],
                         [null, "No te mira cuando lo dice. Al día siguiente, el Bosque está lleno de sombras sin casa que piden dónde dormir. Madreselva les da un lugar. Nadie le dio las gracias."]], end: { xp: 22, flag: ["m8_zonaHondonada", "m8_zonaCedida"] } },
      negar: { say: [["raiz", "Ninguna. Ninguna. Siempre ninguna."],
                     [null, "La soñadora despierta de golpe, llorando. Los robles crujen todos a la vez, y en la otra punta del Bosque se cae el primero, con raíz y todo."],
                     ["madreselva", "Bueno. Ahora sabemos lo que cuesta decirle que no. Uno por vez. Va a seguir pidiendo, y nosotros vamos a seguir atando."]], end: { xp: 24, flag: "m8_zonaNegada" } },
    } },
  });

  /* ---------- Los Altos: el viento que trae la voz y Tarará ---------- */
  add("heights", {
    "e8-paso": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { brisa: "Brisa, la vieja voz del Coro" }, start: "a", nodes: {
      a: { say: [[null, "En el paso más alto de la cumbre, donde el viento sube del fondo, una anciana con cintas de colores descoloridas en el pelo está sentada en una piedra. Tiene los ojos cerrados. Escucha."],
                 ["brisa", "Brisa. Fui la voz del Coro, hace mucho. Ahora soy una vieja que escucha el viento. Y el viento ya no trae canciones. Trae una voz. Pide agua en todos los pasos, con la misma voz."],
                 ["brisa", "Los pastores dicen que es la Raíz. Yo digo que es la Raíz cantando la única canción que sabe. Le cantamos tanto, que aprendió."]],
           opts: [{ t: "«¿Qué pasó con los molinos?»", go: "molinos", once: true },
                  { t: "«Usted rompió los molinos conmigo.»", go: "libre", cNeed: "m7_libre", once: true },
                  { t: "«Usted cantó en los doce molinos a la vez.»", go: "unico", cNeed: "m7_unico", once: true },
                  { t: "Pedirle que cante contra el viento, como antes", go: "cantar" },
                  { t: "Escuchar lo que dice la voz", go: "escuchar" },
                  { t: "«Que los Altos le contesten. Una sola respuesta, de toda la cumbre.»", go: "contestar" }] },
      molinos: { say: [["brisa", "Algunos siguen ahí, viejos. Otros se los llevó el viento. Ya nadie canta adentro. No hace falta. La Raíz canta sola, y nadie se la puede vender a nadie."],
                       ["brisa", "Tanto pelear por tener la canción de moda. La canción de moda ahora es una sed."]], back: "a" },
      libre: { say: [["brisa", "Me acuerdo. Tomé el hacha primero. Dije que qué alivio. Fue un alivio, unos años. Después vino el miedo, como dije también."],
                     ["brisa", "Nadie me creyó cuando dije que la voz del viento era de la Raíz. Ya no le creían a nadie que cantara. Ni a mí."]], back: "a" },
      unico: { say: [["brisa", "Me acuerdo. La canción la elegí yo, al final. Lenta, simple. Le cantamos eso cada noche, treinta años. Ahora el viento me la devuelve, torcida, con su voz."],
                     ["brisa", "Es como oír a un chico repetir lo que le gritaste. Una se arrepiente de todo lo que le gritó."]], back: "a" },
      cantar: { say: [[null, "Brisa se para, despacio. Abre la boca y canta, frente al viento. Tiene la voz gastada, quebrada. Igual se mete en los huesos."],
                      [null, "Por un rato, en ese paso, el viento lleva su canción y no la voz de abajo. Después se le acaba el aire. Se sienta. La voz de la Raíz vuelve."],
                      ["brisa", "Antes duraba más. Antes valía más. Igual, por un rato, la tapé. Gracias por pedírmelo."]], end: { xp: 12, flag: "e8_brisaCanta" } },
      escuchar: { say: [[null, "Te sientas a su lado y cierras los ojos. El viento sube tibio desde el fondo. Al principio es solo ruido. Después se entiende."],
                        [null, "«Agua. Lugar. La primera. Devuélvanme a la primera. La que bebió y se fue volando hacia la luz»."],
                        ["brisa", "¿Lo oyó? Habla de alguien. Siempre de alguien. Como una madre que llama a un hijo por la ventana."]], end: { xp: 14, flag: "e8_brisaEscucha" } },
      contestar: { say: [["brisa", "¿Contestarle? ¿Con qué? ¿Con una canción? Ya no tengo Coro."],
                         [null, "No con una canción, le dices: con una respuesta. Brisa lo piensa. Esa semana, los cinco pueblos de los Altos se juntan en el paso. Discuten tres días qué decirle a la Raíz."],
                         [null, "Al final, todos juntos, gritan hacia el fondo una sola frase: «Te escuchamos. No tenemos agua para darte. Tenemos lugar en la mesa». El viento se queda quieto un momento largo."],
                         ["brisa", "No sé si entendió. Pero es la primera vez en mi vida que la cumbre dice algo sin venderlo."]], end: { xp: 20, flag: ["e8_altosResponden", "u8_altos"] } },
    } },

    "e8-tarara": { kind: "dialogo", need: { era: 8, layer: 2 }, who: { tarara: "Tarará, del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En el mirador viejo de la cumbre, una mujer de treinta y tantos años está sentada en el borde, con las piernas colgando hacia el vacío. Mueve los labios sin hacer ruido."],
                 ["tarara", "Tarará, del Prado. Me conoció de niña, creo. Cuando no paraba de cantar. Usted vino a mi casa. Mi madre se acuerda todavía."],
                 ["tarara", "Ahora oigo la voz. La de abajo. Más clara que nadie, dicen Los Que Oyen. Quieren que vaya al templo a hablar por ella."]],
           opts: [{ t: "«¿Todavía canta con las manos?»", go: "manos", cNeed: "m7_tararaManos" },
                  { t: "«¿Se acuerda de alguna canción?»", go: "callada", cNeed: "m7_tararaCallada" },
                  { t: "«¿Sigue cantando dormida?»", go: "canta", cNeed: "m7_tararaCanta" },
                  { t: "«¿Qué dice la voz?»", go: "voz", once: true },
                  { t: "«Vaya al templo. Que hable por ella alguien que la oye de verdad.»", go: "templo" },
                  { t: "«No vaya. Usted no le debe su boca a nadie.»", go: "no" }] },
      manos: { say: [["tarara", "(Mueve las manos, con soltura) Todos los días. Adentro sigo oyendo todo. Afuera, silencio. Arpegia me enseñó, antes de morir. Ahora le enseño a los chicos que oyen demasiado."],
                     ["tarara", "La Raíz no oye las manos. Por eso puedo hablar de ella sin que se entere."]], back: "a" },
      callada: { say: [["tarara", "Ninguna. Ni la nana. Mi madre me la cantó toda la vida y nunca se me pegó. La sombra de olvido me dejó limpia."],
                       ["tarara", "Por eso la voz de abajo me entra tan clara. No hay nada adentro que la tape. Soy una pieza vacía donde ella habla."]], back: "a" },
      canta: { say: [["tarara", "Todas las noches. Ahora canto lo de abajo. Mis vecinos dicen que la Raíz aprendió las canciones de mí, que yo se las canté dormida durante treinta años."],
                     ["tarara", "Puede ser. Le canté todo lo que el Claro olvidó. Ahora ella se acuerda. Yo no."]], back: "a" },
      voz: { say: [["tarara", "Que tiene sed. Que tiene miedo de que la vuelvan a dormir con una canción. Que la primera que bebió le debe algo. Y otra cosa, que Los Que Oyen no repiten."],
                   ["tarara", "Que está cansada de que hablen por ella. Que quiere su propia boca. Eso no lo dicen en el templo."]], back: "a" },
      templo: { say: [["tarara", "¿Hablar por ella? ¿Todo el día?"],
                      [null, "Mira el vacío un rato largo. Después se levanta."],
                      ["tarara", "Bueno. Alguien la va a hablar igual. Mejor alguien que diga también lo que no conviene. Lo de la boca propia. Eso lo voy a decir yo."]], end: { xp: 16, flag: "e8_tararaTemplo" } },
      no: { say: [["tarara", "No le debo mi boca a nadie. Lo dice como si fuera fácil."],
                  [null, "Se queda en el mirador. Esa noche, la voz de abajo la busca, más fuerte que nunca. Tarará se tapa los oídos con las manos y canta algo propio, desafinado, hasta dormirse."],
                  ["tarara", "La próxima vez que venga, cánteme algo usted. Para tener una voz de más, por si la mía no alcanza."]], end: { xp: 18, flag: "e8_tararaPropia" } },
    } },
  });

  /* ---------- Hondonada Umbría: la savia que vuelve a propósito y las setas ---------- */
  add("hollow", {
    "e8-niscalo": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { niscalo: "Níscalo, de la Casa de la Seta", fosca: "Fosca, de la Corte Velada" }, start: "a", nodes: {
      a: { say: [[null, "En la Hondonada, alguien abrió zanjas largas en el suelo. Por ellas corre savia negra, despacio. A los dos lados crecen setas negras que brillan de noche, como brasas."],
                 ["niscalo", "Níscalo, de la Casa de la Seta. Mi abuelo Moho cantaba para las setas. Yo no canto: cavo. La savia vuelve, y donde hay savia hay setas. Las setas curan fiebres, sueños malos, la tos del Fondo. Por primera vez, nadie de la Seta pasa hambre."],
                 [null, "Al borde de la zanja, una sombra alta, delgada como humo, lo mira con los brazos cruzados."],
                 ["fosca", "Fosca, de la Corte Velada. Estas zanjas pasan por donde dormimos. La savia nos moja. Y las setas que brillan no nos dejan escondernos. Nos sacaron la noche."]],
           opts: [{ t: "«¿Su familia cavaba el hielo, hace mucho?»", go: "esporina", cNeed: "m2_setaCava", once: true },
                  { t: "«¿Por qué la Seta siempre se quedó atrás?»", go: "atras", once: true },
                  { t: "Ayudar a Níscalo a cavar otra zanja", go: "cavar" },
                  { t: "Tapar la zanja que pasa por donde duermen las sombras", go: "tapar" },
                  { t: "«Que la Seta comparta las setas con la Corte. Y que cave lejos de donde duermen.»", go: "compartir" }] },
      esporina: { say: [["niscalo", "La tatarabuela Esporina. Tenemos su pala colgada en la casa. Cavó en el hielo del Fondo para curar a treinta enfermos, y la Raíz se volteó en sueños."],
                        ["niscalo", "Cada vez que la Seta cava, algo se mueve abajo. Lo sabemos. Cavamos igual. Nadie más cura lo que curamos."]], back: "a" },
      atras: { say: [["niscalo", "Porque crecemos donde nadie quiere vivir. En el hielo, en la sombra, en lo podrido. Cuando el Claro está sano, las setas se mueren y nosotros con ellas."],
                     ["niscalo", "Cuando el Claro está enfermo, nos vienen a buscar. Nadie nos quiere cerca cuando está bien. ¿Entiende lo que es eso? Que te convenga que los demás estén mal."]], back: "a" },
      cavar: { say: [[null, "Cavas con él hasta el mediodía. La savia entra a la zanja nueva, tibia, y en una hora ya asoman las primeras setas."],
                     ["niscalo", "Esto vale una semana de comida para mi casa. Tome su parte."],
                     [null, "Fosca no dice nada. Se va con las otras sombras, más lejos, hacia el borde de la Hondonada, donde todavía hay oscuridad."]], end: { xp: 10, coins: 15, flag: "e8_setaCava" } },
      tapar: { say: [[null, "Tapas la zanja con tierra y piedras. La savia se desvía hacia otro lado. Las setas del borde se apagan, una por una."],
                     ["niscalo", "Ahí había remedio para veinte casas. Para veinte. ¿Usted les va a llevar otro?"],
                     ["fosca", "Gracias. Esta noche dormimos. Mañana va a cavar otra, un poco más allá. Así es con la Seta."]], end: { xp: 12, flag: "e8_zanjaTapada" } },
      compartir: { say: [["niscalo", "¿Compartir? ¿Con ellas? Nunca compraron una seta."],
                         ["fosca", "Nunca nos vendieron una."],
                         [null, "Se miran mucho rato. Al final, Níscalo cierra la zanja que pasa por donde duermen las sombras y abre otra, más larga, del otro lado. Le da a Fosca una canasta de setas."],
                         ["fosca", "Las que curan los sueños malos. Las vamos a usar. Desde que la Raíz habla, las sombras soñamos con ella."],
                         ["niscalo", "Que no se diga que la Seta solo comparte cuando le sobra. Aunque es lo que estoy haciendo."]], end: { xp: 20, flag: ["e8_setaReparte", "u8_sombra"] } },
    } },

    "e8-setas": { kind: "dialogo", need: { era: 8, layer: 2 }, who: { niscalo: "Níscalo, de la Casa de la Seta" }, start: "a", nodes: {
      a: { say: [[null, "Un hombre de la Casa de la Seta, con las uñas negras de tierra, te lleva a los campos grandes de la Seta, al fondo de la Hondonada. Son kilómetros de setas negras sobre savia, brillando bajo un cielo sin estrellas. Huele a sótano y a pan."],
                 ["niscalo", "Níscalo, de la Seta. Esto da de comer a la Casa entera. Cura medio Claro. Y cada seta que cortamos, la Raíz la siente. Despierta un poco más. Bebe un poco más de los ríos, para reponer."],
                 ["niscalo", "Los Que Oyen dicen que la Raíz despierta es buena para nosotros. Los del Prado dicen que la estamos despertando nosotros. Las dos cosas son verdad. ¿Qué hago con mis campos?"]],
           opts: [{ t: "«¿Qué pasa si la Raíz se duerme de nuevo?»", go: "duerme", once: true },
                  { t: "Dejar que la Seta coseche", go: "cosecha" },
                  { t: "Quemar los campos de setas", go: "quemar" },
                  { t: "«Coseche solo las setas que curan. Las otras, déjelas.»", go: "remedios" }] },
      duerme: { say: [["niscalo", "Se mueren las setas. Todas. Como pasó en tiempos de la tatarabuela, cuando la savia se aclaró. La Seta vuelve a ser la que pide."],
                      ["niscalo", "Por eso la Casa quiere que siga despierta. Soñando, dicen algunos. Ni dormida ni despierta: soñando. Eso sería lo mejor para nosotros. No sé si para nadie más."]], back: "a" },
      cosecha: { say: [[null, "Níscalo asiente. Esa semana, la Seta cosecha todo. Las carretas salen llenas hacia el Prado, el Cráter, el Fondo. Por primera vez, la Casa de la Seta compra tierras en el Prado."],
                       [null, "Esa noche, todos los soñadores del Claro gritan a la vez. La Raíz no se calma. Pero tampoco se enoja: bebe. Los ríos bajan un dedo."],
                       ["niscalo", "Nadie nos va a volver a dejar atrás. Lo pagamos con algo. No sé con qué todavía."]], end: { xp: 22, coins: 20, flag: "m8_setaCosecha" } },
      quemar: { say: [[null, "Níscalo te mira como si le hubieras pegado. Después, en silencio, trae antorchas."],
                      [null, "Los campos arden toda la noche. Las setas negras chisporrotean y largan un humo dulce. La Raíz, abajo, se queda quieta, como un animal que deja de doler."],
                      ["niscalo", "Ya está. Mañana la Seta no tiene nada. Otra vez. Si la Raíz se duerme, no va a ser gracias a nosotros. Va a ser por nosotros, como siempre."]], end: { xp: 22, flag: "m8_setaQuemada" } },
      remedios: { say: [["niscalo", "¿Solo las que curan? Son un tercio. Las demás son las que se venden."],
                        [null, "Lo piensa toda la noche. Al amanecer, manda cosechar solo las setas de los remedios. Las otras se quedan, brillando, sin que nadie las toque."],
                        ["niscalo", "La Casa no va a ser rica. Va a ser necesaria. Mi abuelo decía que eso es peor, porque te buscan solo cuando duele. Vamos a ver."]], end: { xp: 20, flag: "m8_setaRemedios" } },
    } },
  });

  /* ---------- Lago Espejo: lo que la Raíz quiere ---------- */
  add("lake", {
    "e8-espejo": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { bajamar: "Bajamar, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla del Lago Espejo hay gente arrodillada, bebiendo con las manos, sin parar. Tienen la panza hinchada y siguen bebiendo. Una mujer de las Mareas, mojada hasta la cintura, los aparta del agua uno por uno."],
                 ["bajamar", "Bajamar, de las Mareas. El lago ya no muestra lo que recuerda. Muestra lo que quiere la Raíz. Y la Raíz quiere agua. Quien se asoma, siente su sed. Y bebe por ella."],
                 ["bajamar", "Las Mareas vivimos en el agua. Ahora el agua nos da miedo. No sé qué hacer con eso."]],
           opts: [{ t: "Asomarte al lago", go: "mirar" },
                  { t: "Cubrir la orilla con lonas para que nadie se asome", go: "tapar" },
                  { t: "«Que las Mareas le lleven agua al Corazón. Que no tenga que pedirla por boca de nadie.»", go: "llevar" }] },
      mirar: { say: [[null, "Te asomas. El agua está quieta. Abajo, en el reflejo, no estás tú: hay un río que baja hacia el fondo del Claro, y al final del río, una luz chica que se aleja volando."],
                     [null, "Sientes una sed enorme, de mil años. Bajamar te agarra del brazo antes de que te agaches."],
                     ["bajamar", "¿Qué vio? No me diga agua. Todos dicen agua. ¿Qué más?"]], end: { xp: 14, flag: "e8_espejoMira" } },
      tapar: { say: [[null, "Con Bajamar y tres vecinos cubren la orilla con lonas viejas, atadas a estacas. Nadie puede asomarse. La gente se queda sentada del otro lado, con sed, sin saber de qué."],
                     ["bajamar", "Funciona. Por ahora. Pero un lago tapado es un lago que nadie cuida. Ya veo a los chicos levantando las puntas para mirar."]], end: { xp: 12, flag: "e8_espejoTapado" } },
      llevar: { say: [["bajamar", "¿Llevarle agua? ¿Al tocón? ¿En baldes?"],
                      [null, "En cántaros. Esa semana, las Mareas organizan una fila: cántaros de agua del lago, de mano en mano, desde la orilla hasta el Corazón. Tardan un día entero."],
                      [null, "Vuelcan el agua al pie del tocón. La tierra la traga en un segundo. Esa noche, el lago muestra el cielo otra vez, por primera vez en un mes."],
                      ["bajamar", "Una noche de paz por un día de fila. No es buen negocio. Pero es el primero que hacemos con ella en lugar de contra ella."]], end: { xp: 20, flag: ["e8_mareasAgua", "u8_agua"] } },
    } },
  });

  /* ---------- Cuevas del Eco: el eco que contesta ---------- */
  add("caves", {
    "e8-eco": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { caliza: "Caliza, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En los túneles de las Cuevas nadie habla. Los mineros se comunican con golpes en la pared. Una minera de la Hondura, con la cara blanca de polvo, te pone un dedo en los labios antes de que digas nada."],
                 ["caliza", "(En voz muy baja) Caliza, de la Hondura. No hable fuerte. El eco ya no repite. Contesta. Con voz propia, lenta, desde abajo. Ayer un muchacho preguntó en broma «¿hay alguien?», y el eco le dijo su nombre."],
                 ["caliza", "Desde entonces el muchacho no duerme. Los demás no hablan. La Hondura trabaja en silencio. Así no se puede vivir mucho tiempo."]],
           opts: [{ t: "Preguntarle algo al eco", go: "preguntar" },
                  { t: "Tapar el túnel que contesta", go: "tapar" },
                  { t: "«Que la Hondura escriba en la piedra lo que contesta el eco.»", go: "escribir" }] },
      preguntar: { say: [[null, "Te paras en el túnel. Caliza se aleja, tapándose los oídos. Preguntas lo primero que se te ocurre: «¿Qué quieres?»"],
                         [null, "El eco tarda. Después contesta, desde muy abajo: «Dormir. Sin sed. Sin que me canten. Sin que me prometan. Dormir porque quiero, no porque me obligan»."],
                         ["caliza", "Eso es más de lo que le contestó a nadie. ¿Por qué a usted? ¿Qué le debe?"]], end: { xp: 16, flag: "e8_ecoPregunta" } },
      tapar: { say: [[null, "Con Caliza y dos mineros traen piedras y cierran el túnel del eco. Golpean la última piedra con el martillo. El golpe no vuelve."],
                     ["caliza", "Ya está. Ahora hay un túnel menos. La Hondura tiene muchos. El eco va a buscar otro."]], end: { xp: 12, flag: "e8_ecoTapado" } },
      escribir: { say: [["caliza", "¿Escribir? ¿Como en las paredes viejas, las de los versos de tambor?"],
                        [null, "Lo hacen. Durante una semana, un minero pregunta y Caliza graba en la piedra, con cincel, lo que contesta el eco. Cada respuesta, con fecha."],
                        [null, "Al final de la semana hay una pared entera. La gente de la Hondura viene a leerla en silencio. Hay cosas sobre la sed, sobre el miedo, sobre alguien que bebió primero. Hay una sola línea repetida diez veces: «No me escuchan, me usan»."],
                        ["caliza", "Ahora no lo puede decir nadie por ella. Lo dijo ella, y está en la piedra. Que lo lean los que vienen."]], end: { xp: 20, flag: ["e8_ecoEscrito", "u8_piedra"] } },
    } },
  });

  /* ---------- El Fondo Blanco: el templo de Los Que Oyen y los soñadores ---------- */
  add("deep", {
    "e8-templo": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { ensuena: "Ensueña, voz de Los Que Oyen" }, start: "a", nodes: {
      a: { say: [[null, "En el Fondo Blanco, sobre la Tumba Helada, hay un templo de hielo con las paredes tan finas que se ve la luz de adentro. Adentro duermen cien soñadores a la vez, en filas, con una cinta gris en la muñeca."],
                 ["ensuena", "Ensueña, voz de Los Que Oyen. Le doy la bienvenida al lugar donde por fin la escuchamos. Siete generaciones le cantaron para que se callara. Nosotros la despertamos para que hablara. Es un pueblo más. El más viejo."],
                 ["ensuena", "Todo lo que sueño viene de ella. Anoche soñé con la sopa de mi madre. Eso quiere decir que la Raíz extraña algo tibio. Todo tiene sentido, si uno escucha."]],
           opts: [{ t: "«Hace mucho, yo llevé la cinta gris.»", go: "cinta", cNeed: "m2_oyenUnido", once: true },
                  { t: "«Hace generaciones entregué soñadores a la Regente.»", go: "entrega", cNeed: "m2_oyenEntrega", once: true },
                  { t: "«¿La sopa de su madre no será solo la sopa de su madre?»", go: "sopa", once: true },
                  { t: "Entrar a escuchar con los soñadores", go: "entrar" },
                  { t: "«Dejen entrar a la guardia del Fondo. Que el templo no sea solo de ustedes.»", go: "guardia" },
                  { t: "Irte del templo", go: "irte" }] },
      cinta: { say: [["ensuena", "Lo sabemos. Está escrito en la pared de la entrada: los primeros que se unieron. Hay uno sin nombre, solo dice «el Cuidador del Vado». Pensé que era una leyenda."],
                     ["ensuena", "Si fue usted, entonces empezó todo esto. Gracias. O perdón. Todavía no sé cuál."]], back: "a" },
      entrega: { say: [[null, "Ensueña se queda callada un rato. Algunos soñadores, en las filas, se voltean dormidos."],
                       ["ensuena", "La Regente Albina los sacó del Fondo, con su ayuda. Mi tatarabuela era una de ellos. Volvió a soñar a escondidas, en un sótano, durante cuarenta años. No le guardo rencor. Ella sí, hasta que murió."]], back: "a" },
      sopa: { say: [["ensuena", "Nada es solo lo que es. Eso enseñamos aquí."],
                    [null, "Lo dice muy segura. Pero se toca la cinta de la muñeca, despacio, como quien busca algo en un bolsillo vacío."]], back: "a" },
      entrar: { say: [[null, "Te acuestas en una fila, entre dos soñadores. Ensueña te ata una cinta gris en la muñeca. Cierras los ojos."],
                      [null, "Sueñas con agua que baja, con una polilla que se aleja hacia la luz, con mil años de gente cantando arriba. Y con la sopa de una madre que no conoces."],
                      [null, "Al despertar no sabes qué parte era de la Raíz y qué parte de la mujer de al lado. Ensueña sonríe: dice que todo era de la Raíz."]], end: { xp: 14, flag: "e8_temploEscucha" } },
      guardia: { say: [["ensuena", "¿La guardia? ¿Los que cantan la nana para dormirla? Vienen a callarla."],
                       [null, "Le explicas que no: a mirar. A cuidar a los que duermen, como en el Prado. Que si la Raíz es un pueblo, los otros pueblos tienen que poder entrar a verla."],
                       [null, "Ensueña tarda una semana en decidir. Al final abre las puertas. La guardia del Fondo entra en silencio, sin cantar, y se sienta entre las filas."],
                       ["ensuena", "Si es un pueblo, que la vean los demás pueblos. Tiene razón. Me molesta que tenga razón."]], end: { xp: 20, flag: ["e8_temploGuardia", "u8_escarcha"] } },
      irte: { say: [["ensuena", "Va a volver. Todos vuelven. Cuando empiezan a soñar con ella, vuelven."],
                    [null, "Sales al frío. Esa noche, en tu casa, sueñas con agua que baja. Tu criatura te despierta lamiéndote la cara."]], end: { xp: 8, flag: "e8_temploFuera" } },
    } },

    "e8-sonadores": { kind: "dialogo", need: { era: 8, layer: 2 }, who: { ensuena: "Ensueña, voz de Los Que Oyen" }, start: "a", nodes: {
      a: { say: [[null, "Afuera del templo, en el hielo, una mujer con una cinta gris en la muñeca reparte cintas grises a una fila larga de gente de todos los pueblos. Gente del Prado, del Cráter, de los Altos. Todos dicen haber soñado con la Raíz."],
                 ["ensuena", "Ensueña, voz de Los Que Oyen. Cada día vienen más. Dicen que la Raíz les habló. Algunos repiten cosas que ya dijo. Otros dicen cosas nuevas. Nosotros anotamos todo. Todo es su voz."],
                 ["ensuena", "En el Prado dicen que mentimos. Que inventamos lo que nos conviene. ¿Usted qué cree?"]],
           opts: [{ t: "«¿Cómo saben qué parte es de la Raíz?»", go: "como", once: true },
                  { t: "Creerles", go: "creer" },
                  { t: "Probar si mienten", go: "probar" },
                  { t: "Soñar tú también, para saberlo", go: "sonar" }] },
      como: { say: [["ensuena", "Porque sueñan cosas que no saben. Una niña del Cráter soñó con un farolero que ayuna en el Corazón. Nunca bajó al Corazón."],
                    ["ensuena", "Y porque si fuera inventado, sería más lindo. Nadie inventa una sed así."]], back: "a" },
      creer: { say: [[null, "Le dices que les crees. Ensueña te abraza fuerte, de golpe, sin pedir permiso."],
                     [null, "Esa semana, Los Que Oyen bajan al Prado con tu nombre en la boca: el Cuidador del Vado nos cree. La fila del templo se hace el doble de larga."],
                     ["ensuena", "Desde hoy, lo que soñamos tiene peso. Gracias. Ahora hay que soñar bien. Eso me da más miedo que antes."]], end: { xp: 24, flag: "m8_creer" } },
      probar: { say: [[null, "Le propones una prueba: tú le cuentas a la Raíz, en el Corazón, una cosa que nadie más sabe. Después vemos si algún soñador la repite."],
                      [null, "Esa noche, en el Corazón, le dices al tocón en voz baja el nombre de la primera criatura que cuidaste. Tres días después, dos soñadores lo repiten. Otros veinte dicen otra cosa, cada uno distinta."],
                      ["ensuena", "Dos. Dos la oyeron de verdad. Y veinte soñaron lo que querían soñar. Yo también, a lo mejor. Ya no sé qué parte de mí es ella."]], end: { xp: 24, flag: "m8_mienten" } },
      sonar: { say: [[null, "Tomas una cinta gris. Esa noche duermes en el templo, entre los soñadores, sin que nadie te diga qué soñar."],
                     [null, "Sueñas con una sed de mil años, con una polilla, con un río. Y en algún momento la sed te habla, sin palabras, directo a ti. Te reconoce."],
                     [null, "Al despertar, tienes la boca seca. Desde esa noche sueñas con ella cada tanto. Ensueña dice que ahora eres parte de Los Que Oyen. No dices que no."]], end: { xp: 24, flag: "m8_sonar" } },
    } },
  });

  /* ---------- Corazón del Claro: Hollín, lo que pide la Raíz, el pacto que no oyó y el final ---------- */
  add("heart", {
    "e8-hollin": { kind: "encuentro", need: { era: 8, layer: 1 }, who: { hollin: "Hollín, el que ayuna" }, start: "a", nodes: {
      a: { say: [[null, "Al borde del tocón del Corazón, un hombre muy flaco está sentado en el suelo, cubierto de polillas grises como de un abrigo. Delante tiene un farol viejo, apagado, con el vidrio negro de humo."],
                 ["hollin", "Hollín. Me llamo Hollín. Tiene cara de haberme visto antes. Yo vi muchas caras parecidas. Siempre la misma, me parece: la de quien cuida."],
                 ["hollin", "Ayuno. Hace siglos que ayuno. Creí que con eso pagaba. Ahora la Raíz despertó y me llama por mi nombre de antes, el que tenía cuando la luz salía del suelo y yo tenía alas."]],
           opts: [{ t: "«¿Qué es usted, Hollín?»", go: "que", once: true },
                  { t: "«Hace generaciones me dijo que ayunaba. ¿Sigue?»", go: "ayuno", cNeed: "e2_hollinAyuna", once: true },
                  { t: "«Usted sabía de dónde salía el aceite.»", go: "sabia", cNeed: "faroleroSabia", once: true },
                  { t: "Sentarte con él, a oscuras", go: "oscuras" },
                  { t: "Encender su farol", go: "luz" },
                  { t: "«No se lo va a llevar. Se lo prometo.»", go: "promesa" }] },
      que: { say: [["hollin", "Fui una polilla. Una Estrella, dicen los viejos, de las que brillan. Fui la primera que bebió de la Raíz, cuando su savia era luz y nadie sabía que era de alguien. Bebí y me hice grande. Después me hice hombre, para esconderme entre ustedes."],
                   ["hollin", "Todo lo que el Claro sufrió después empezó en mi boca. Los pozos, los faroles, las guerras por la luz. Por eso no como. Es poco. Es lo que hay."]], back: "a" },
      ayuno: { say: [["hollin", "Sigo. Usted me ofreció pan, aquella vez, y lo dejé para las polillas. Estas son nietas de nietas de aquellas. Comieron por mí todo este tiempo."]], back: "a" },
      sabia: { say: [["hollin", "Lo sabía antes que nadie. Lo sabía porque fui el primero que lo bebió. Treinta años encendiendo faroles con mi propia culpa, y no se lo dije a nadie."],
                     ["hollin", "Nadie más me lo preguntó nunca. Solo usted."]], back: "a" },
      oscuras: { say: [[null, "Te sientas a su lado. Las polillas te rozan la cara. Pasa un rato largo sin que ninguno de los dos diga nada. Abajo, la tierra respira."],
                       ["hollin", "Si me entregan, la Raíz se calma un tiempo. Si no, sigue pidiendo. No sé qué quiero. Quiero que alguien decida por mí, por primera vez en mil años. Es una cobardía. Ya sé."],
                       [null, "Cuando te vas, ya está dormido, sentado. Las polillas se acomodan sobre él como una manta."]], end: { xp: 14, flag: "e8_hollinOscuras" } },
      luz: { say: [[null, "Acercas un fósforo a la mecha. La llama prende. Hollín la mira con la boca abierta, sin pestañear. Las polillas se lanzan contra el vidrio."],
                   [null, "Él estira la mano, despacio, y se detiene a un dedo de la luz. A sus pies, las raíces del tocón se mueven también hacia el farol."],
                   ["hollin", "Déjelo un rato. Quiero ver cuánto aguanto. Mil años y todavía no sé cuánto aguanto."]], end: { xp: 12, flag: "e8_hollinLuz" } },
      promesa: { say: [["hollin", "No prometa. Aquí abajo las promesas se oyen. Ella las oye todas, y se acuerda de todas."],
                       [null, "Pero sonríe, por primera vez. Una sonrisa chica, torcida, de alguien que se olvidó cómo se hacía."],
                       ["hollin", "Igual, gracias. Hace mil años que nadie prometía algo por mí."]], end: { xp: 16, flag: "e8_hollinPromesa" } },
    } },

    "e8-pide": { kind: "encuentro", need: { era: 8, layer: 2 }, who: { ensuena: "Ensueña, voz de Los Que Oyen", hollin: "Hollín, el que ayuna", raiz: "La Raíz, por boca de los soñadores" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, una mujer con una cinta gris en la muñeca duerme de pie frente al tocón. Tiene los ojos abiertos. Cuando habla, la voz no es suya."],
                 ["raiz", "Tengo sed. Tengo miedo. Me acuerdo. La primera bebió de mí y se fue volando. Está aquí. La huelo. Devuélvanmela. Si me la devuelven, duermo. Si no, sigo pidiendo."],
                 [null, "Al lado, un hombre flaco cubierto de polillas no levanta la cabeza."],
                 ["hollin", "Soy yo. Hollín. Me pide a mí. Hace mil años que me pide, pero nunca tan claro."],
                 ["ensuena", "(Despierta de golpe, temblando) Ensueña, soy Ensueña, de Los Que Oyen. ¿Qué dijo? Nunca me acuerdo de lo que dice. ¿Pidió algo?"]],
           opts: [{ t: "«¿Qué le pasa a Hollín si se lo entregamos?»", go: "q1", once: true },
                  { t: "«¿Y si nadie se lo entrega?»", go: "q2", once: true },
                  { t: "Entregarle a Hollín", go: "entregar" },
                  { t: "Negarte", go: "negar" },
                  { t: "Ofrecerte en su lugar", go: "ofrecer" }] },
      q1: { say: [["hollin", "No sé. Vuelvo a ella. Me bebe, como yo la bebí. A lo mejor me hago savia. A lo mejor nada."],
                  ["ensuena", "Los Que Oyen creemos que se calmaría una generación entera. Tal vez dos. Pero lo creemos porque lo soñamos. Ya sabe cómo es eso."]], back: "a" },
      q2: { say: [["ensuena", "Sigue pidiendo. Cada noche más fuerte. Los soñadores ya no descansan. Hay tres en el templo que no despiertan desde hace una semana."],
                  ["hollin", "Por mí. Hay tres que no despiertan por mí. Ya sé. No me lo diga otra vez."]], back: "a" },
      entregar: { say: [[null, "No llegas a decirlo del todo. Hollín se levanta solo, como si lo hubiera estado esperando. Las polillas se levantan con él."],
                        [null, "Camina hasta el tocón y apoya la mano en la madera. Se pone fino como papel. Las polillas se le despegan y se van, todas juntas, hacia arriba, hacia la luz del Prado."],
                        [null, "Donde estaba, queda el farol apagado. Abajo, muy al fondo de la Raíz, se ve por un momento una luz chica, que tiembla."],
                        ["ensuena", "Calló. Por primera vez, en mi boca, calló. No sé si duerme o si está ocupada."]], end: { xp: 30, flag: "m8_hollinEntregado" } },
      negar: { say: [[null, "Dices que no. Que Hollín se queda. La mujer dormida vuelve a hablar con la voz de abajo."],
                     ["raiz", "Entonces sigo pidiendo. Ustedes siempre dicen que no a lo que les pido, y sí a lo que me sacan."],
                     [null, "El suelo tiembla. Las raíces del tocón se retiran despacio, como un brazo que se cruza."],
                     ["hollin", "Gracias. Creo. No sé si gracias. Ahora voy a tener que seguir vivo, y sabiendo."]], end: { xp: 24, flag: "m8_hollinNegado" } },
      ofrecer: { say: [[null, "Pones la mano en el tocón. Dices: tómeme a mí en su lugar. La mujer dormida gira la cabeza hacia ti, despacio."],
                       ["raiz", "Usted no bebió. Pero estuvo cerca. Siempre está cerca. Cada vez que el Claro gira, usted está. Lo acepto un poco."],
                       [null, "Sientes sed. Una sed que no es tuya, que se te queda en la garganta. Desde esa noche, cada tanto, sueñas lo que la Raíz sueña."],
                       ["hollin", "(Llora, sin taparse la cara) Nadie se ofreció por mí. En mil años, nadie."]], end: { xp: 28, flag: "m8_ofrecido" } },
    } },

    "e8-pacto": { kind: "dialogo", need: { era: 8, layer: 2 }, who: { raiz: "La Raíz, por boca de los soñadores" }, start: "a", nodes: {
      a: { say: [[null, "Al pie del tocón, un soñador viejo, del Fondo, duerme sentado con la espalda contra la madera. Cuando llegas, abre los ojos sin despertar. Habla con la voz de abajo."],
                 ["raiz", "Usted. Usted estaba la última vez. Cuando me cantaron todos a la vez. Cuando rompieron el viento. Cuando se prometieron cosas en silencio. Siempre está."],
                 ["raiz", "Yo los escuché mil años. Ahora quiero que me escuchen. Una vez. Sin canción. Sin promesa."]],
           opts: [{ t: "«¿Qué sintió cuando todo el Claro le cantó lo mismo?»", go: "unico", cNeed: "m7_unico", once: true },
                  { t: "«¿Qué sintió cuando se rompieron los molinos?»", go: "libre", cNeed: "m7_libre", once: true },
                  { t: "«¿Sabe de los pactos que se hicieron con las manos?»", go: "manos", cNeed: "m7_manos", once: true },
                  { t: "Contarle uno de los pactos de manos", go: "contar", cNeed: "m7_manos" },
                  { t: "Pedirle perdón", go: "perdon" },
                  { t: "«No le debemos nada. Usted también nos sacó cosas.»", go: "nada" }] },
      unico: { say: [["raiz", "Una sola canción. Toda la noche. Todas las noches. Como una mano sobre la boca. Dormí porque no me dejaban otra cosa."],
                     ["raiz", "Y cada promesa que me cantaban sin querer se me quedaba arriba, flotando. Las Estrellas Mudas son mías. Son lo que no me dijeron en serio."]], back: "a" },
      libre: { say: [["raiz", "Silencio de dueño. Ruido de todos. Me llegaban mil cosas a medias, mil sueños mezclados. Ninguno era para mí. Nadie me hablaba a mí."],
                     ["raiz", "Por eso hablé más fuerte. Y nadie me creyó, porque ya no le creían a nada."]], back: "a" },
      manos: { say: [["raiz", "Sé que hay algo. Los pueblos se miran de una forma que antes no. Cumplen cosas que nunca me dijeron. Hay un pacto, y yo no estoy adentro."],
                     ["raiz", "Mil años fui la que oía todas las promesas. Ahora soy la única que no oye. ¿Sabe lo que es eso? Es como estar afuera de la casa que una sostiene."]], back: "a" },
      contar: { say: [[null, "Le cuentas en voz alta uno de los pactos del Canto de Manos: que el Cráter descansa una hora al día y el Barrio le cuida los hornos mientras tanto."],
                      [null, "El soñador viejo se queda quieto. Después, con la voz de abajo, repite el pacto palabra por palabra, despacio, como quien aprende una oración."],
                      ["raiz", "Ahora lo sé. Uno. Me falta el resto. Pero ahora sé que se puede saber."]], end: { xp: 18, flag: "e8_pactoContado" } },
      perdon: { say: [["raiz", "¿Perdón? ¿Por qué parte?"],
                      [null, "No sabes qué contestar. Hay demasiadas partes. El soñador viejo sonríe con una boca que no es suya."],
                      ["raiz", "Está bien. No sabe. Yo tampoco sabría. Es la primera vez que alguien me pide perdón sin pedirme algo después. Lo guardo."]], end: { xp: 16, flag: "e8_raizPerdon" } },
      nada: { say: [["raiz", "¿Yo les saqué?"],
                    [null, "Le dices: la savia que enfermó al Barrio, los sueños robados, las fiebres, los que no despertaron. El soñador viejo se queda callado mucho rato."],
                    ["raiz", "Yo no sé qué saqué. Yo solo dormía mal. Nunca nadie me dijo que mis sueños dolían. Ahora lo sé. No sé qué hacer con saberlo."]], end: { xp: 18, flag: "e8_raizNada" } },
    } },

    "e8-final": { kind: "dialogo", need: { era: 8, eraWin: "heart" }, first: true, once: true, who: { ensuena: "Ensueña, voz de Los Que Oyen", niscalo: "Níscalo, de la Casa de la Seta", madreselva: "Madreselva, alcaldesa del Bosque", raiz: "La Raíz, por boca de los soñadores" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz Despierta cae, pero no se duerme. Se queda mirando, con los ojos abiertos, desde todas las grietas del Corazón. Frente al tocón están la voz de Los Que Oyen, el hombre de la Seta y la alcaldesa del Bosque. Detrás, cien soñadores dormidos de pie."],
                 ["raiz", "No me duerman. No me canten. Escúchenme o déjenme soñar. Pero no me duerman otra vez."],
                 ["ensuena", "Ensueña, de Los Que Oyen: que tenga voto. Que sea un pueblo, el décimo. Si los nueve la aceptan, la Raíz decide con nosotros. Para eso la despertamos."],
                 ["niscalo", "Níscalo, de la Seta: que sueñe sin dormir. Ni despierta del todo ni dormida. La Seta vive de eso. Y el Claro come de la Seta. Es lo menos malo."],
                 ["madreselva", "Madreselva, del Bosque: que se duerma. Con la nana, como siempre. Ya sé lo que cuesta: una estatua más. Pero conozco ese precio. Los otros dos no los conozco."]],
           opts: [{ t: "«¿Qué pasa si la Raíz vota?»", go: "q1", once: true },
                  { t: "«¿Qué pasa si sueña sin dormir?»", go: "q2", once: true },
                  { t: "«¿Qué pasa si le cantamos la nana otra vez?»", go: "q3", once: true },
                  { t: "Aceptar a la Raíz como el décimo pueblo", go: "voto", cNeed: "e8_nueve" },
                  { t: "Cantarle la nana, como siempre", go: "nana" },
                  { t: "Dejar que sueñe despierta", go: "despierta" }] },
      q1: { say: [["ensuena", "Vota. Decide con nosotros, en cada cosa que la toque. Y la toca todo: cada pozo, cada siembra, cada canción."],
                  ["madreselva", "Y pide lugar. Un pueblo nuevo necesita tierra. Es el más grande de todos, y tiene sed. Los otros nueve se van a tener que apretar."]], back: "a" },
      q2: { say: [["niscalo", "Sueña sin parar, y su sueño se derrama un poco hacia arriba. Todos van a soñar un poco despiertos. Las setas van a crecer en todas partes."],
                  ["ensuena", "Y nadie va a distinguir bien qué es real. Ni ella. Eso Níscalo no lo dice."]], back: "a" },
      q3: { say: [["madreselva", "Se duerme. Por un tiempo. Alguien se queda de piedra en el Corazón, como siempre que alguien la duerme. Una estatua más."],
                  ["raiz", "Y yo vuelvo a soñar mal, sola, abajo. Y un día alguien me vuelve a despertar. Ustedes ya saben cómo sigue."]], back: "a" },
      voto: { say: [[null, "Llegan los nueve: el Barrio con sus rondas, las Casas con sus faroles del otro lado, el Gremio con sus grietas a medias, el Concejo que escuchó a los robles, la cumbre que contestó, las sombras con sus setas, las Mareas con sus cántaros, la Hondura con su pared escrita, la guardia del Fondo que entró al templo."],
                    [null, "Uno por uno, frente al tocón, cada pueblo dice lo mismo: «Te aceptamos». La Raíz escucha. Por primera vez en mil años, nadie le canta y nadie le promete. Le preguntan."],
                    ["raiz", "¿Un pueblo? ¿Yo? Entonces quiero lugar. Quiero agua. Quiero votar en todo. Soy grande. Tengo sed."],
                    [null, "Los nueve se miran. Ya lo sabían. Esa misma semana, en todas las zonas, la gente empieza a correr las cercas para hacerle lugar a la Raíz."]], end: { xp: 60, flag: "m8_voto" } },
      nana: { say: [[null, "Madreselva empieza la nana, bajito. Ensueña llora y no canta. Níscalo tampoco. Tú cantas con Madreselva, y tu criatura también."],
                    [null, "La Raíz cierra los ojos, uno por uno, en todas las grietas. Lo último que dice, con la voz de cien soñadores, es: «Otra vez»."],
                    [null, "Al amanecer, en el Corazón, hay una estatua nueva. Es Madreselva, de pie, con la boca abierta en la última nota. Los soñadores despiertan y no se acuerdan de nada."],
                    ["ensuena", "Durmió. Como siempre. Y alguien pagó. Como siempre. Esto no se termina nunca, ¿verdad?"]], end: { xp: 60, flag: "m8_nana" } },
      despierta: { say: [[null, "Níscalo se arrodilla frente al tocón y deja sobre la tierra una seta negra, la más grande de su Casa. La Raíz la mira. Después cierra los ojos a medias."],
                         [null, "No duerme. No despierta. Sueña. Y su sueño sube por las grietas como un vapor tibio, hacia el Prado, el Cráter, los Altos, el Vado."],
                         [null, "Esa noche, en todo el Claro, la gente camina por la calle sin saber si está dormida. Tu criatura te mira raro, como si tú también estuvieras un poco en otra parte."],
                         ["niscalo", "Ya está. Nadie la va a dormir y nadie la va a escuchar del todo. Las setas van a crecer en todos lados. Mañana vamos a saber si eso era bueno. O no vamos a saber nunca."]], end: { xp: 60, flag: "m8_despierta" } },
    } },
  });
})(window.EVEVENTS);
